//! WebKit's inspector protocol, as Playwright's WebKit build speaks it:
//! typed commands, their responses and events, generated by
//! `chromiumoxide_pdl` from the vendored `protocol/protocol.json` (the
//! same generator as Chrome's protocol in `chromiumoxide_cdp`).
//!
//! Commands implement [`chromiumoxide_types::Command`]; their
//! `identifier()` is the WebKit method name (`Page.navigate`).

#[allow(clippy::multiple_bound_locations)]
#[allow(clippy::derive_partial_eq_without_eq)]
#[allow(clippy::large_enum_variant)]
#[allow(unreachable_patterns)]
#[allow(deprecated)]
#[allow(dead_code)]
#[rustfmt::skip]
pub mod webkit;

/// The Playwright WebKit build `protocol/protocol.json` comes from.
pub const WEBKIT_BUILD: u32 = 2388;
